import{z as s,x as i,o as t,c as p,q as E,j as A,D as e,d as n,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Vega 桶与曲面风险","description":"","frontmatter":{"title":"Vega 桶与曲面风险","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vega-buckets.md","filePath":"quant/vega-buckets.md","lastUpdated":1791063341000}'),B={name:"quant/vega-buckets.md"};function u(d,a,m,g,h,D){const r=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=E('<h1 id="vega-桶与曲面风险" tabindex="-1">Vega 桶与曲面风险 <a class="header-anchor" href="#vega-桶与曲面风险" aria-label="Permalink to &quot;Vega 桶与曲面风险&quot;">​</a></h1><div class="epigraph"><p>一个总 Vega 把微笑的水平、斜率和弯曲捆在一起；桶风险是按到期与 Delta 把曲面节点当成可 bump 的市场数据。</p><footer>—— 对照 Derman 对波动率曲面风险的论述；桶划分见期权风险报告惯例</footer></div><p><a href="/quant/pathwise-likelihood-ratio">上一课</a>给出如何估 \\(\\partial V/\\partial\\theta\\)。本课的 \\(\\theta\\) 不再是一个 \\(\\sigma\\)，而是<strong>曲面上的一排节点</strong>。主干 <a href="/quant/vol-surface">隐波曲面</a> 与 <a href="/quant/greeks-hedge">Delta 对冲</a> 已写水平和局部对冲。缺口是报告：结构产品的风险要按桶加总，才能拿去对冲香草。后课曲面动态再把桶随时间怎么一起动写进去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BSM Vega 是价值对常数 \\(\\sigma\\) 的导。真实市场动的是一张 \\((T,K)\\) 或 \\((T,\\Delta)\\) 网格。总 Vega 可能接近 0，同时短到期数字桶和长到期斜度桶都很大——autocallable、cliquet 典型如此。问题是定义 bump：按原始报价惯例（FX 的 ATM/RR/BF，股权的按 \\(K\\) 或按 \\(\\Delta\\)）去 bump，再通过无套利插值传到定价引擎，而不是在引擎内部的参数（Heston \\(\\kappa,\\nu\\)）上 bump 再假装那是市场 Vega。</p><p><span class="marginnote">数字实例：某 autocallable 短到期数字桶 \\(+50\\) 万 vega、长到期斜度桶 \\(-49\\) 万，合计 \\(+1\\) 万——报表上一行「总 Vega」几乎无害；但短桶隐波 bump 1 点组合就盈亏 50 万。总数字是代数和，风险是分布：桶不拆开，一切都看不见。</span></p><p>桶边界是设定：到期 1M/3M/1Y、Delta 25/10 等。边界一改，同一组合的「最大桶」会换位置。报告必须固定网格，校准与 AAD 的输入应对齐这张网格。</p><h3 id="模型-vega-不是市场-vega" tabindex="-1">模型 Vega 不是市场 Vega <a class="header-anchor" href="#模型-vega-不是市场-vega" aria-label="Permalink to &quot;模型 Vega 不是市场 Vega&quot;">​</a></h3><p>在 <a href="/quant/heston">Heston</a> 里对 \\(\\nu\\) 求导，是模型参数敏感度，用于校准与模型风险。市场 Vega 是对可交易香草价格（或隐波节点）的导数。对冲只能买后者。把 Heston Vega 拿去下香草单，单位都对不上。AAD 若以曲面节点为输入，输出的才是市场桶；若以模型参数为输入，输出的是另一张表，两张都要，不要合并成一行「Vega」。</p>',9)),(t(),A(o,null,{default:e(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20MV%5B%22%E6%A8%A1%E5%9E%8B%20Vega%3A%20%E5%AF%B9%20Heston%20%CE%BD%20%E6%B1%82%E5%AF%BC%22%5D%20--%3E%20U1%5B%22%E7%94%A8%E4%BA%8E%3A%20%E6%A0%A1%E5%87%86%E8%AF%8A%E6%96%AD%E3%80%81%E6%A8%A1%E5%9E%8B%E9%A3%8E%E9%99%A9%22%5D%0A%20%20MKV%5B%22%E5%B8%82%E5%9C%BA%E6%A1%B6%3A%20%E5%AF%B9%E9%9A%90%E6%B3%A2%E8%8A%82%E7%82%B9%E6%B1%82%E5%AF%BC%22%5D%20--%3E%20U2%5B%22%E7%94%A8%E4%BA%8E%3A%20%E9%99%90%E9%A2%9D%E3%80%81%E4%B8%8B%E9%A6%99%E8%8D%89%E5%8D%95%E5%AF%B9%E5%86%B2%22%5D%0A%20%20MV%20-.%20%22%E5%AF%B9%E8%B1%A1%E4%B8%8D%E5%90%8C%2C%20%E4%B8%8D%E5%8F%AF%E5%90%88%E5%B9%B6%22%20.-%3E%20MKV%0A%20%20MKV%20--%3E%20OK%5B%22%E8%83%BD%E5%AF%B9%E4%B8%8A%E5%8F%AF%E4%BA%A4%E6%98%93%E5%B7%A5%E5%85%B7%22%5D%0A%20%20MV%20-.%20%22%E5%8D%95%E4%BD%8D%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%20.-%3E%20OK%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">平行 bump 整张曲面，近似「水平」风险，对偏斜产品会漏掉主风险。至少要水平、倾斜、弯曲三个情景，或完整桶矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选择与报价一致的节点；用 <a href="/quant/arb-free-iv">无套利插值</a> 填充。每个节点 bump 1 个波动点（或按 RR/BF 的惯例 bump），重估或用 AAD。加总到内部限额：按到期、按货币、按标的。对冲：用该桶附近的香草或方差互换去减最大项，残差进次主桶。数字与障碍在对应 \\(K\\) 的短到期桶上会出尖峰，对冲应用价差而不是 ATM。</p><p><span class="marginnote">术语翻译：「bump 1 个波动点」就是把该节点的隐含波动率从 \\(20\\%\\) 改成 \\(21\\%\\)，其他不动，重算一遍组合价值，差值除以 \\(1\\%\\) 就是这个桶的 vega。整张风险表就是把这动作在网格上重复几十次（或用 AAD 一次算完）。</span></p><p>利率与股权混合结构要同时报 IR 桶与 EQ 桶，不要把一切折成「股权总 Vega」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>定价映射 \\(\\mathrm{surface}\\mapsto V\\) 的 Jacobian 就是桶风险。插值核决定 bump 如何传染邻居：局部插值让桶更「对角」，全局参数化（SVI 全期限一个参数）会让一次 bump 污染整张曲面，报告看起来平滑、对冲却对不上可交易工具。这就是为什么桶应定义在报价节点上，而不是定义在内部参数上。</p>',7)),(t(),A(o,null,{default:e(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Quote%5B%22%E6%8A%A5%E4%BB%B7%E8%8A%82%E7%82%B9%20ATM%20RR%20%E6%88%96%20K%22%5D%20--%3E%20Interp%5B%22%E6%97%A0%E5%A5%97%E5%88%A9%E6%8F%92%E5%80%BC%22%5D%0A%20%20Interp%20--%3E%20Eng%5B%22%E5%AE%9A%E4%BB%B7%E5%BC%95%E6%93%8E%22%5D%0A%20%20Eng%20--%3E%20Buck%5B%22AAD%20%E6%88%96%20bump%20%E7%9A%84%E6%A1%B6%20Jacobian%22%5D%0A%20%20Buck%20--%3E%20Hdg%5B%22%E7%94%A8%E5%8F%AF%E4%BA%A4%E6%98%93%E9%A6%99%E8%8D%89%E5%87%8F%E4%B8%BB%E6%A1%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流动性：10 Delta 翼部 bump 1 点可能比 ATM 1 点贵得多，名义风险与可对冲风险不同。跳空使短到期桶的已实现与 bump 情景不一致。XVA 的曲面风险还含对手方与自身曲线，后课再接。不要用历史 PCA 的第一主成分去替代当日桶——那是下一课动态，不是今日对冲清单。</p><p><span class="marginnote">常见误区：初学者容易把「桶上有风险」等同「桶能被对冲」。10 Delta 远翼名义 vega 很大，但那里买卖价差宽、成交即移位，真去对冲反而把风险钉进报价。限额表应同时给出名义桶与「按可对冲工具折算」的桶，二者差的就是流动性折价。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总 Vega 不够；风险是曲面上按报价惯例定义的桶。</li><li>市场桶与模型参数敏感度必须分表。</li><li>插值核会污染邻居，桶应钉在可交易节点上。</li><li>出处：曲面作为市场数据见 Derman 等关于波动率的论述；报告网格是市场惯例。</li></ul>',5))])}const b=s(B,[["render",u]]);export{_ as __pageData,b as default};
